const choice = (id, prompt, options, answer, explanation) => ({
  id, type: 'choice', prompt, options, answer, explanation,
});

const fill = (id, prompt, answers, explanation) => ({
  id, type: 'fill', prompt, answers, explanation,
});

const expandGrammarItem = ([
  id, title, level, category, functions, structure, explanation, usage,
  examples, notes, questions,
]) => ({
  id, title, level, levelSource: '备考资料', verificationStatus: '待核验',
  category, functions, structure, explanation, usage, examples, notes, questions,
});

